#include <cstdio>
#include <cstring>
#include <string>

using namespace std;

class FastInput {
    static const int SIZE = 1 << 20;
    char buffer[SIZE];
    int index = 0, size = 0;

    char readChar() {
        if (index >= size) {
            size = static_cast<int>(fread(buffer, 1, SIZE, stdin));
            index = 0;
            if (size == 0) return 0;
        }
        return buffer[index++];
    }

public:
    bool readInt(int &value) {
        char c;
        do {
            c = readChar();
            if (!c) return false;
        } while (c <= ' ');

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readChar();
        }

        value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = readChar();
        }
        value *= sign;
        return true;
    }
};

int ad[20006][11];
int sent[20006][11];
int recvCount[11];

