        memset(sent, 0, sizeof(sent));
        memset(recvCount, 0, sizeof(recvCount));

        for (int i = 0; i < K; ++i) {
            int n, m;
            input.readInt(n);
            input.readInt(m);
            ++sent[n][m];
            ++recvCount[m];
        }

        string output;
        output.reserve(static_cast<size_t>(N) * 12);

        for (int n = 1; n <= N; ++n) {
            long long count = 0;
