    char buffer[SIZE];
    int position = 0, length = 0;

    char getChar() {
        if (position >= length) {
            length = static_cast<int>(fread(buffer, 1, SIZE, stdin));
            position = 0;
            if (length == 0) return 0;
        }
        return buffer[position++];
    }

public:
    bool readInt(int& value) {
