        value *= sign;
        return true;
    }
};

class FastOutput {
    static const int SIZE = 1 << 20;
    char buffer[SIZE];
    int position = 0;

public:
    ~FastOutput() {
        flush();
    }

    void flush() {
        if (position) {
            fwrite(buffer, 1, position, stdout);
            position = 0;
        }
    }

    void putChar(char c) {
        if (position == SIZE) flush();
        buffer[position++] = c;
    }

    void writeInt(long long value) {
        if (value == 0) {
