#include <bits/stdc++.h>
using namespace std;

class FastInput {
    static constexpr size_t SIZE = 1 << 20;
    char buffer[SIZE];
    size_t pos = 0, len = 0;

    char getChar() {
        if (pos == len) {
            len = fread(buffer, 1, SIZE, stdin);
            pos = 0;
            if (len == 0) return '\0';
        }
        return buffer[pos++];
    }

public:
    template <typename T>
    bool readInt(T& value) {
        char c;
        do {
            c = getChar();
            if (c == '\0') return false;
        } while (c <= ' ');

        bool negative = false;
        if (c == '-') {
            negative = true;
            c = getChar();
        }

        value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = getChar();
        }

        if (negative) value = -value;
        return true;
    }
};

int main() {
    FastInput input;
    int N, M;
    long long K;
    string output;
    output.reserve(1 << 20);

    while (input.readInt(N) && input.readInt(M) && input.readInt(K)) {
        vector<unsigned char> ad(static_cast<size_t>(N) * M);
        vector<long long> sent(static_cast<size_t>(N) * M, 0);
        vector<long long> received(M, 0);

        for (int n = 0; n < N; ++n) {
            for (int m = 0; m < M; ++m) {
                int value;
                input.readInt(value);
                ad[static_cast<size_t>(n) * M + m] = (value != 0);
            }
        }

        for (long long i = 0; i < K; ++i) {
            int n, m;
            input.readInt(n);
            input.readInt(m);
            --n;
            --m;
            ++sent[static_cast<size_t>(n) * M + m];
            ++received[m];
        }

        for (int n = 0; n < N; ++n) {
            long long count = 0;
            for (int m = 0; m < M; ++m) {
                size_t index = static_cast<size_t>(n) * M + m;
                if (ad[index]) {
                    count += received[m] - sent[index];
                }
            }

            if (n > 0) output.push_back(' ');
            char number[32];
            auto result = to_chars(number, number + sizeof(number), count);
            output.append(number, result.ptr);
        }
        output.push_back('\n');

        if (output.size() >= (1u << 20)) {
            fwrite(output.data(), 1, output.size(), stdout);
            output.clear();
        }
    }

    fwrite(output.data(), 1, output.size(), stdout);
    return 0;
}

